/**
 * PWA service-worker registration (Req 1.4). The worker (generated by
 * vite-plugin-pwa) precaches the app shell and the bundled snapshot so the app
 * works offline on later launches. Registration is best-effort and never blocks
 * or breaks the app if service workers are unavailable.
 */
export function registerPwa(): void {
  if (!('serviceWorker' in navigator)) return;
  if (import.meta.env.DEV) return; // only register the real SW in production builds

  window.addEventListener('load', () => {
    // The virtual module is provided by vite-plugin-pwa at build time.
    import('virtual:pwa-register')
      .then(({ registerSW }) => {
        registerSW({ immediate: true });
      })
      .catch(() => {
        // offline-first still works from cache; ignore registration errors
      });
  });
}
